def capitalize_sentences(text):
    sentences = []
    current_sentence = []

    result_parts = []

    sentence_enders = ['.', '!', '?']
    i = 0
    while i < len(text):
        char = text[i]
        current_sentence.append(char)
        if char in sentence_enders:
            sentences.append("".join(current_sentence))
            current_sentence = []
        i += 1

    if current_sentence:
        sentences.append("".join(current_sentence))

    final_sentences = []
    for sentence in sentences:
        stripped_sentence = sentence.lstrip()
        if not stripped_sentence:
            final_sentences.append(sentence)
            continue

        first_char_idx = sentence.find(stripped_sentence[0])
        if first_char_idx != -1:
            capitalized_sentence = (
                sentence[:first_char_idx] +
                stripped_sentence[0].upper() +
                stripped_sentence[1:]
            )
            final_sentences.append(capitalized_sentence)
        else:
            final_sentences.append(sentence)

    return "".join(final_sentences)

