        self.balance = initial_balance
        self.transactions = []
        self.deposits_log = []
        self.withdrawals_log = []
        self.failed_attempts = {}
        self.notes = []

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            self.transactions.append(('deposit', amount))
            self.deposits_log.append(amount)
            return True
        self.notes.append("Deposit amount must be positive.")
        return False

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            self.transactions.append(('withdraw', amount))
            self.withdrawals_log.append(amount)
            return True
        elif amount <= 0:
            self.notes.append("Withdrawal amount must be positive.")
            return False
        else:
